function normalize(intervals) {
  if (!Array.isArray(intervals)) throw new RangeError('Expected an array of intervals');
  const sorted = [];
  for (const pair of intervals) {
    if (!Array.isArray(pair) || pair.length !== 2) {
      throw new RangeError('Expected a [start, end] pair');
    }
    const [start, end] = pair;
    if (!Number.isFinite(start) || !Number.isFinite(end) || start > end) {
      throw new RangeError('Invalid interval endpoints');
    }
    if (start < end) sorted.push([start, end]);
  }
  sorted.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const merged = [];
  for (const pair of sorted) {
    const last = merged[merged.length - 1];
    if (last && pair[0] <= last[1]) {
      last[1] = Math.max(last[1], pair[1]);
    } else {
      merged.push(pair);
    }
  }
  return merged;
}

export function subtractIntervals(base, cuts) {
  const bases = normalize(base);
  const exclusions = normalize(cuts);
  const result = [];
  let j = 0;

  for (const [start, end] of bases) {
    let cursor = start;
    while (j < exclusions.length && exclusions[j][1] <= cursor) j++;

    while (j < exclusions.length && exclusions[j][0] < end) {
      const [cutStart, cutEnd] = exclusions[j];
      if (cutStart > cursor) result.push([cursor, cutStart]);
      cursor = Math.max(cursor, cutEnd);
      if (cursor >= end) break;
      j++;
    }

    if (cursor < end) result.push([cursor, end]);
  }
  return result;
}

